window.products.push({"id":914889,"name":"Nicole Miller New York Peterson Cotton Blend Tuxedo Tab Top Light Filtering Curtain Panels, 54\"x 63\", Slate Blue, Set of 2","category":"homeandappliances","retail price":34.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81MxZuRSPGL._AC_SL1500_.jpg","description":"The Nicole Miller New York Peterson Tuxedo Tab Top Light Filtering Curtain Panels are designed with cotton-blend solid, textured fabric and feature pointed, tab-top styling with self-covered button accents for an elegant look. The light-filtering curtains diffuse light beautifully while providing privacy in your space. Hang them with your favorite curtain rod for an added decorative touch. The tab top treatment fits curtain rods up to 1.5\" in diameter. The panels are machine washable for easy care.","images":["https://m.media-amazon.com/images/I/81MxZuRSPGL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Nicole Miller","source_asin":"B08X2R7D3Z","category_path":"Home & Kitchen"},"sku":"BM-914889","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08X2R7D3Z","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08X2R7D3Z","price_pending":true,"merchant_ready":false});
